    website: 'https://www.idx.co.id/'
  }
};

// Data untuk kategori saham
const stockCategories = [
  {
    name: 'Indeks',
    stocks: [
      { symbol: '^JKSE', name: 'IDX Composite' },
      { symbol: 'IDXBASIC.JK', name: 'IDX Basic Industry' },
      { symbol: 'IDXINDUST.JK', name: 'IDX Industrial' },
      { symbol: 'IDXFINANCE.JK', name: 'IDX Finance' },
      { symbol: 'IDXENERGY.JK', name: 'IDX Energy' }
    ]
  },
  {
    name: 'Perbankan',
    stocks: [
      { symbol: 'BBCA.JK', name: 'Bank Central Asia' },
      { symbol: 'BBRI.JK', name: 'Bank Rakyat Indonesia' },
      { symbol: 'BMRI.JK', name: 'Bank Mandiri' },
      { symbol: 'BBNI.JK', name: 'Bank Negara Indonesia' },
      { symbol: 'BJTM.JK', name: 'Bank Jatim' }
    ]
  },
  {
    name: 'Teknologi',
    stocks: [
      { symbol: 'GOTO.JK', name: 'GoTo Gojek Tokopedia' },
      { symbol: 'BUKA.JK', name: 'Bukalapak' },
      { symbol: 'TLKM.JK', name: 'Telkom Indonesia' },
      { symbol: 'EXCL.JK', name: 'XL Axiata' },
      { symbol: 'ISAT.JK', name: 'Indosat Ooredoo Hutchison' }
    ]
  },
  {
    name: 'Konsumer',
    stocks: [
      { symbol: 'UNVR.JK', name: 'Unilever Indonesia' },
      { symbol: 'ICBP.JK', name: 'Indofood CBP' },
      { symbol: 'INDF.JK', name: 'Indofood Sukses Makmur' },
      { symbol: 'HMSP.JK', name: 'HM Sampoerna' },
      { symbol: 'KLBF.JK', name: 'Kalbe Farma' }
    ]
  }
];

// Fungsi untuk mendeteksi apakah simbol adalah saham Indonesia
const isIndonesianStock = (stockSymbol) => {
  return stockSymbol.endsWith('.JK') ||
    stockSymbol === '^JKSE' ||
    stockSymbol === 'IDXENERGY.JK' ||
    stockSymbol === 'IDXBASIC.JK' ||
    stockSymbol === 'IDXINDUST.JK' ||
    stockSymbol === 'IDXNONCYC.JK' ||
    stockSymbol === 'IDXCYCLIC.JK' ||
    stockSymbol === 'IDXHEALTH.JK' ||
    stockSymbol === 'IDXFINANCE.JK' ||
    stockSymbol === 'IDXTECHNO.JK' ||
    stockSymbol.startsWith('^IDX');
};

// Custom hook untuk interval functionality
function useInterval(callback, delay) {
  const savedCallback = useRef();

  // Remember the latest callback
  useEffect(() => {
    savedCallback.current = callback;
  }, [callback]);

  // Set up the interval
  useEffect(() => {
    function tick() {
      savedCallback.current();
    }
    if (delay !== null) {
      const id = setInterval(tick, delay);
      return () => clearInterval(id);
    }
  }, [delay]);
}

// Custom hook untuk API fetching dengan cache
const useStockAPI = () => {
  const [cache, setCache] = useState({});
  const [cacheExpiry, setCacheExpiry] = useState({});
  const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes
  
  const fetchStock = useCallback(async (params, forceRefresh = false) => {
    const { symbol, interval, period, start_date, end_date } = params;
    
    // Create a cache key based on all params
    const cacheKey = JSON.stringify(params);
    
    // Get current time
    const now = new Date().getTime();
    
    // Check cache first if no force refresh
    if (!forceRefresh && cache[cacheKey] && cacheExpiry[cacheKey] && cacheExpiry[cacheKey] > now) {
      console.log(`Using cached data for ${symbol} with params:`, params);
      return cache[cacheKey];
    }
    
    // If not cached or expired, fetch from API
    try {
      const res = await axios.get("http://localhost:5000/stock", { params });
      
      if (res.data && res.data.data && Array.isArray(res.data.data)) {
        // Process data
        const sortedData = [...res.data.data].sort((a, b) => {
          const dateA = new Date(a.Date || a.Datetime);
          const dateB = new Date(b.Date || b.Datetime);
          return dateB - dateA; // Descending order
        });
        
        // Cache the data
        setCache(prevCache => ({
          ...prevCache,
          [cacheKey]: {
            data: sortedData,
            status: 'success',
            timestamp: now
          }
        }));
        
        setCacheExpiry(prevExpiry => ({
          ...prevExpiry,
          [cacheKey]: now + CACHE_DURATION
        }));
        
        return {
          data: sortedData,
          status: 'success',
          timestamp: now
        };
      } else {
        throw new Error('Invalid data format received from server');
      }
    } catch (err) {
      console.error('Error fetching stock data:', err);
      
      // Cache error for 1 minute to prevent constant retries on same error
      const errorResponse = {
        data: [],
        status: 'error',
        error: err.response?.data?.error || err.message || 'Unknown error',
        timestamp: now
      };
      
      setCache(prevCache => ({
        ...prevCache,
        [cacheKey]: errorResponse
      }));
      
      setCacheExpiry(prevExpiry => ({
        ...prevExpiry,
        [cacheKey]: now + 60000 // Cache errors for 1 minute
      }));
      
      return errorResponse;
    }
  }, [cache, cacheExpiry]);
  
  const preloadStockData = useCallback(async (symbols, interval = '1d', period = '5d') => {
    // Batch process to avoid overwhelming the API
    const batchSize = 5;
    const batches = [];
    
    // Split symbols into batches
    for (let i = 0; i < symbols.length; i += batchSize) {
      batches.push(symbols.slice(i, i + batchSize));
    }
    
    // Process each batch
    for (const batch of batches) {
      const promises = batch.map(symbol => {
        return fetchStock({
          symbol,
          interval,
          period
        });
      });
      
      await Promise.all(promises);
      
      // Small delay between batches
      if (batches.length > 1) {
        await new Promise(resolve => setTimeout(resolve, 300));
      }
    }
  }, [fetchStock]);
  
  // Clear expired cache entries
  useEffect(() => {
    const cleanupInterval = setInterval(() => {
      const now = new Date().getTime();
      let hasExpired = false;
      
      const newCacheExpiry = { ...cacheExpiry };
      
      // Check for expired items
      Object.entries(cacheExpiry).forEach(([key, expiry]) => {
        if (expiry < now) {
          delete newCacheExpiry[key];
          hasExpired = true;
        }
      });
      
      // Only update if something expired
      if (hasExpired) {
        setCacheExpiry(newCacheExpiry);
        
        // Also clean up the actual cache data
        const newCache = { ...cache };
        Object.keys(cache).forEach(key => {
          if (!newCacheExpiry[key]) {
            delete newCache[key];
          }
        });
        
        setCache(newCache);
      }
    }, 60000); // Check every minute
    
    return () => clearInterval(cleanupInterval);
  }, [cache, cacheExpiry]);
  
  return {
    fetchStock,
    preloadStockData,
    cache,
    clearCache: () => {
      setCache({});
      setCacheExpiry({});
    }
  };
};

function App() {
  // State for navigation
  const [currentPage, setCurrentPage] = useState('home');
  const [urlParams, setUrlParams] = useState(null);
  const [pageParams, setPageParams] = useState({});
  
  // Stock API with cache
  const { fetchStock, preloadStockData } = useStockAPI();

  // Handler untuk navigasi
const handleNavigation = useCallback((page, params = {}) => {
  setCurrentPage(page);
  setPageParams(params);
  
  // State untuk DevNoticeModal
  const [showDevNotice, setShowDevNotice] = useState(false);
  // Cek localStorage untuk DevNoticeModal
  useEffect(() => {
    const hasAcknowledged = localStorage.getItem('devNoticeAcknowledged');
    
    if (!hasAcknowledged) {
      setShowDevNotice(true);
      document.body.classList.add('modal-open');
    } else if (hasAcknowledged !== 'permanent') {
      const acknowledgedTime = parseInt(hasAcknowledged, 10);
      const oneWeek = 7 * 24 * 60 * 60 * 1000;
      
      if (Date.now() - acknowledgedTime > oneWeek) {
        setShowDevNotice(true);
        document.body.classList.add('modal-open');
      }
    }
  }, []);
  // Handler untuk menutup modal
  const handleCloseDevNotice = (dontShowAgain) => {
    setShowDevNotice(false);
    document.body.classList.remove('modal-open');
    
    if (dontShowAgain) {
      localStorage.setItem('devNoticeAcknowledged', 'permanent');
    } else {
      localStorage.setItem('devNoticeAcknowledged', Date.now().toString());
    }
  };
  
  // Update URL jika perlu
  const url = page === 'home' ? '/' : `/${page}`;
  if (Object.keys(params).length > 0) {
    const searchParams = new URLSearchParams();
    Object.entries(params).forEach(([key, value]) => {
      searchParams.append(key, value);
    });
    window.history.pushState({}, '', `${url}?${searchParams.toString()}`);
  } else {
    window.history.pushState({}, '', url);
  }
  
  // Scroll ke atas halaman
  window.scrollTo(0, 0);
}, []);

  // Check for URL parameters on component mount
  useEffect(() => {
    const handleNavigation = () => {
      const path = window.location.pathname;
      const searchParams = new URLSearchParams(window.location.search);
      const symbolParam = searchParams.get('symbol');

      if (path === '/stocks' || path.includes('/stocks')) {
        setCurrentPage('stocks');
        if (symbolParam) {
          setUrlParams({ symbol: symbolParam });
        }
      } else if (path === '/news' || path.includes('/news')) {
        setCurrentPage('news');
      } else if (path === '/about' || path.includes('/about')) {
        setCurrentPage('about');
      } else {
        setCurrentPage('home');
      }
    };

    // Initial navigation check
    handleNavigation();

    // Listen for popstate events (browser back/forward buttons)
    window.addEventListener('popstate', handleNavigation);

    return () => {
      window.removeEventListener('popstate', handleNavigation);
    };
  }, []);

  // Navigation function wrapped in useCallback
  const navigate = useCallback((page, params = {}) => {
    let url = page === 'home' ? '/' : `/${page}`;

    // Add query parameters if provided
    if (Object.keys(params).length > 0) {
      const searchParams = new URLSearchParams();
      Object.entries(params).forEach(([key, value]) => {
        searchParams.append(key, value);
      });
      url += `?${searchParams.toString()}`;
    }

    // Update browser history
    window.history.pushState({}, '', url);

    // Update state
    setCurrentPage(page);
    setUrlParams(params);
    
    // Scroll to top
    window.scrollTo(0, 0);
  }, []);

  // State variables for stock functionality
  const [symbol, setSymbol] = useState('');
  const [stockData, setStockData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [currencySymbol, setCurrencySymbol] = useState('Rp');
  const [realtime, setRealtime] = useState(false);
  const [refreshInterval, setRefreshInterval] = useState(30000);
  const [lastFetched, setLastFetched] = useState(null);
  const [dataInfo, setDataInfo] = useState({
    isRealtime: false,
    delay: "15-20 minutes",
    source: "Yahoo Finance"
  });
  const [showChart, setShowChart] = useState(true);
  const [chartPeriod, setChartPeriod] = useState('1mo');
  const [chartInterval, setChartInterval] = useState('1d');
  const [useDateRange, setUseDateRange] = useState(false);
  const [chartType, setChartType] = useState('composed');
  const [activeSymbol, setActiveSymbol] = useState('');

  // State for dropdown and category management
  const [showStocksList, setShowStocksList] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterTimeout, setFilterTimeout] = useState(null);

  // State for storing last prices of stocks
  const [stockPrices, setStockPrices] = useState({});
  const [loadingPrices, setLoadingPrices] = useState(false);

  // State for tracking screen width
  const [windowWidth, setWindowWidth] = useState(typeof window !== 'undefined' ? window.innerWidth : 1200);

  // State for preloaded categories
  const [preloadedCategories, setPreloadedCategories] = useState({});
  
  // State for visible stocks in dropdown (lazy loading)
  const [visibleStocks, setVisibleStocks] = useState(8);

  // Refs
  const symbolInputRef = useRef(null);
  const dropdownRef = useRef(null);

  // Calculate default dates (1 month ago to current date)
  const oneMonthAgo = new Date();
  oneMonthAgo.setMonth(oneMonthAgo.getMonth() - 1);

  const [startDate, setStartDate] = useState(formatDateForInput(oneMonthAgo));
  const [endDate, setEndDate] = useState(formatDateForInput(new Date()));

  // Memoized handlers
  const memoizedFetchStockData = useCallback(async (symbolToFetch = null) => {
    // Use provided symbol or current symbol state
    const stockSymbol = symbolToFetch || symbol;

    // Jika tidak ada symbol, jangan fetch data
    if (!stockSymbol.trim()) {
      setStockData([]);
      setError(null);
      setLastFetched(null);
      return;
    }

    setLoading(true);
    setError(null);
    // Update activeSymbol dan symbol state
    setActiveSymbol(stockSymbol);
    if (symbolToFetch) setSymbol(stockSymbol);

    const params = {
      symbol: stockSymbol,
      interval: chartInterval
    };

    // Use custom date range or standard period
    if (useDateRange && startDate && endDate) {
      params.start_date = startDate;
      params.end_date = endDate;
    } else {
      params.period = chartPeriod;
    }

    try {
      // Using our optimized fetchStock function from useStockAPI
      const result = await fetchStock(params);
      
      if (result.status === 'success' && result.data?.length > 0) {
        // Determine currency symbol based on stock symbol
        const usesIndonesianCurrency = isIndonesianStock(stockSymbol);
        setCurrencySymbol(usesIndonesianCurrency ? 'Rp' : '$');

        // Update data info
        setDataInfo({
          isRealtime: false,
          delay: usesIndonesianCurrency ? "15 minutes" : "15-20 minutes",
          source: "Yahoo Finance (yfinance)"
        });

        setStockData(result.data);
        setLastFetched(new Date(result.timestamp));

        // Update stock price in state
        if (result.data.length > 1) {
          const latest = result.data[0];
          const previous = result.data[1];

          setStockPrices(prevPrices => ({
            ...prevPrices,
            [stockSymbol]: {
              price: latest.Close,
              change: latest.Close - previous.Close,
              changePercent: ((latest.Close - previous.Close) / previous.Close) * 100,
              timestamp: result.timestamp
            }
          }));
        }
      } else {
        // Handle error case
        setError(result.error || 'No data available');
        setStockData([]);
      }
    } catch (err) {
      console.error('Error details:', err);
      setStockData([]);
      setError(`Failed to fetch data: ${err.message}`);
    } finally {
      setLoading(false);
    }
  }, [
    symbol,
    chartInterval,
    useDateRange,
    startDate,
    endDate,
    chartPeriod,
    fetchStock
  ]);

  // Effect for window resize listener with debounce
  useEffect(() => {
    let resizeTimer;
    
    const handleResize = () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        setWindowWidth(window.innerWidth);
      }, 100);
    };

    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
      clearTimeout(resizeTimer);
    };
  }, []);

  // Effect to handle clicks outside of dropdown
  useEffect(() => {
    function handleClickOutside(event) {
      if (
          dropdownRef.current &&
          !dropdownRef.current.contains(event.target) &&
          !event.target.closest('.enhanced-stock-item') &&
          !event.target.closest('.enhanced-stock-dropdown') &&
          !event.target.closest('.stock-category-tabs')
      ) {
        setShowStocksList(false);
      }
    }

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  // Calculate if we're in mobile view
  const isMobileView = windowWidth < 768;
  
  // Preload popular stocks data
  useEffect(() => {
    // Preload only once when component mounts
    if (!preloadedCategories.popular) {
      // Slight delay to allow the main UI to render first
      const timer = setTimeout(() => {
        const symbols = popularStocks.map(stock => stock.symbol);
        console.log('Preloading popular stocks data...');
        preloadStockData(symbols, '1d', '5d')
          .then(() => {
            console.log('Popular stocks preloaded');
            setPreloadedCategories(prev => ({ ...prev, popular: true }));
          })
          .catch(err => console.error('Failed to preload popular stocks:', err));
      }, 2000);
      
      return () => clearTimeout(timer);
    }
  }, [preloadedCategories, preloadStockData]);

  // Fetch stock prices for dropdown with optimized batch processing
  const fetchLatestPricesForCategory = useCallback(async (categoryIndex) => {
    if (loadingPrices) return;
    
    setLoadingPrices(true);
    
    const stocks = stockCategories[categoryIndex].stocks;
    const symbols = stocks.map(stock => stock.symbol);
    
    try {
      // Using our preloadStockData function from useStockAPI
      await preloadStockData(symbols, '1d', '5d');
      
      // Mark this category as preloaded
      setPreloadedCategories(prev => ({
        ...prev,
        [categoryIndex]: true
      }));
      
    } catch (error) {
      console.error("Failed to fetch category prices:", error);
    } finally {
      setLoadingPrices(false);
    }
  }, [loadingPrices, preloadStockData]);

  // Fetch popular stocks data when needed
  const fetchLatestPricesForPopular = useCallback(async () => {
    if (loadingPrices || preloadedCategories.popular) return;
    
    setLoadingPrices(true);
    
    const symbols = popularStocks.map(stock => stock.symbol);
    
    try {
      await preloadStockData(symbols, '1d', '5d');
      setPreloadedCategories(prev => ({
        ...prev,
        popular: true
      }));
    } catch (error) {
      console.error("Failed to fetch popular prices:", error);
    } finally {
      setLoadingPrices(false);
    }
  }, [loadingPrices, preloadStockData, preloadedCategories.popular]);
  
  // Effect to load data when dropdown is shown
  useEffect(() => {
    if (showStocksList) {
      if (selectedCategory !== null && !preloadedCategories[selectedCategory]) {
        fetchLatestPricesForCategory(selectedCategory);
      } else if (selectedCategory === null && !preloadedCategories.popular) {
        fetchLatestPricesForPopular();
      }
    }
  }, [
    showStocksList, 
    selectedCategory, 
    preloadedCategories, 
    fetchLatestPricesForCategory, 
    fetchLatestPricesForPopular
  ]);

  // Debounce function for search filtering
  const filterStocks = useCallback((term) => {
    setSearchTerm(term);

    if (filterTimeout) {
      clearTimeout(filterTimeout);
    }

    const timeout = setTimeout(() => {
      // Search logic is applied via the getFilteredStocks function
      // No action needed here since state is already updated
      console.log(`Search applied for term: ${term}`);
    }, 300);

    setFilterTimeout(timeout);
  }, [filterTimeout]);

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (filterTimeout) {
        clearTimeout(filterTimeout);
      }
    };
  }, [filterTimeout]);

  // Memoized filtered stocks list for performance
  const filteredStocks = useMemo(() => {
    if (!searchTerm) {
      return [];
    }

    const term = searchTerm.toLowerCase();

    // Flatten all stocks and filter
    const allStocks = stockCategories.reduce((acc, category) => {
      return [...acc, ...category.stocks];
    }, [...popularStocks]);

    return allStocks.filter((stock, index, self) =>
        (stock.symbol.toLowerCase().includes(term) ||
            stock.name.toLowerCase().includes(term)) &&
        index === self.findIndex(s => s.symbol === stock.symbol)
    );
  }, [searchTerm]);

  // Helper functions
  function formatDateForInput(date) {
    return date.toISOString().split('T')[0];
  }

  function formatDateTime(dateString) {
    if (!dateString) return '-';

    const date = new Date(dateString);
    if (isNaN(date.getTime())) return dateString;

    return date.toLocaleString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    });
  }

  function formatPrice(price, currency = 'Rp') {
    if (price === null || price === undefined) return '-';
    return `${currency} ${price.toLocaleString('id-ID')}`;
  }

  function getRelativeTime(date) {
    if (!date) return '';

    const seconds = Math.floor((new Date() - date) / 1000);

    let interval = Math.floor(seconds / 31536000);
    if (interval > 1) return `${interval} years ago`;
    if (interval === 1) return '1 year ago';

    interval = Math.floor(seconds / 2592000);
    if (interval > 1) return `${interval} months ago`;
    if (interval === 1) return '1 month ago';

    interval = Math.floor(seconds / 86400);
    if (interval > 1) return `${interval} days ago`;
    if (interval === 1) return '1 day ago';

    interval = Math.floor(seconds / 3600);
    if (interval > 1) return `${interval} hours ago`;
    if (interval === 1) return '1 hour ago';

    interval = Math.floor(seconds / 60);
    if (interval > 1) return `${interval} minutes ago`;
    if (interval === 1) return '1 minute ago';

    return seconds < 5 ? 'just now' : `${seconds} seconds ago`;
  }

  // Handle keyboard Enter for input field
  const handleKeyDown = useCallback((e) => {
    if (e.key === 'Enter' && symbol.trim()) {
      e.preventDefault();
      memoizedFetchStockData();
      setShowStocksList(false);
    } else if (e.key === 'Escape') {
      setShowStocksList(false);
    } else if (e.key === 'ArrowDown' && showStocksList) {
      e.preventDefault();
      // Logic for keyboard navigation could go here
    }
  }, [symbol, showStocksList, memoizedFetchStockData]);

  // Handle selection dari dropdown
  const handleStockSelect = useCallback((selectedSymbol) => {
    // Validate input
    if (!selectedSymbol || typeof selectedSymbol !== 'string') {
      console.error('Invalid symbol provided to handleStockSelect:', selectedSymbol);
      return;
    }

    // Close dropdown immediately for better UX
    setShowStocksList(false);

    // Update the symbol state
    setSymbol(selectedSymbol);

    // Navigate to stocks page if we're not already there
    if (currentPage !== 'stocks') {
      navigate('stocks', { symbol: selectedSymbol });
    }

    // Fetch data immediately
    memoizedFetchStockData(selectedSymbol);
  }, [memoizedFetchStockData, currentPage, navigate]);

  // Set up real-time updates for active symbol
  useInterval(() => {
    if (realtime && activeSymbol.trim()) {
      memoizedFetchStockData(activeSymbol);
    }
  }, refreshInterval);

  // Effect to handle URL parameter for symbol
  useEffect(() => {
    if (urlParams && urlParams.symbol && currentPage === 'stocks') {
      setSymbol(urlParams.symbol);
      memoizedFetchStockData(urlParams.symbol);
    }
  }, [urlParams, currentPage, memoizedFetchStockData]);

  // Memoized StockItem component to prevent unnecessary re-renders
  const StockItem = React.memo(({ stock, category = 'populer' }) => {
    const priceData = stockPrices[stock.symbol];
    const isLoading = loadingPrices && !priceData;

    const isPositive = priceData && priceData.change > 0;
    const isNegative = priceData && priceData.change < 0;

    return (
      <div
        className="enhanced-stock-item"
        onClick={() => handleStockSelect(stock.symbol)}
      >
        <div className="stock-item-content">
          <div className="stock-item-info">
            <div className="stock-item-symbol">{stock.symbol}</div>
            <div className="stock-item-name">{stock.name}</div>
          </div>

          {isLoading ? (
            <div className="stock-item-price">
              <div className="price-skeleton"></div>
            </div>
          ) : priceData ? (
            <div className="stock-item-price">
              <div className="price-value">{formatPrice(priceData.price, stock.symbol.endsWith('.JK') ? 'Rp' : '$')}</div>
              <div className={`price-change ${isPositive ? 'positive' : isNegative ? 'negative' : 'neutral'}`}>
                <span className="price-change-icon">
                  {isPositive ? '▲' : isNegative ? '▼' : '•'}
                </span>
                <span className="price-change-value">
                  {isPositive ? '+' : isNegative ? '-' : ''}{Math.abs(priceData.change).toFixed(2)} ({isPositive ? '+' : isNegative ? '-' : ''}{Math.abs(priceData.changePercent).toFixed(2)}%)
                </span>
              </div>
            </div>
          ) : (
            <div className="stock-item-price">
              <div className="price-value">-</div>
            </div>
          )}
        </div>
      </div>
    );
  }, (prevProps, nextProps) => {
    // Prevent unnecessary re-renders
    if (prevProps.stock.symbol !== nextProps.stock.symbol) return false;
    
    const prevPrice = stockPrices[prevProps.stock.symbol];
    const nextPrice = stockPrices[nextProps.stock.symbol];
    
    // If price data has changed, allow re-render
    if (!prevPrice && nextPrice) return false;
    if (prevPrice && !nextPrice) return false;
    if (prevPrice && nextPrice && prevPrice.price !== nextPrice.price) return false;
    
    // No change, prevent re-render
    return true;
  });

  // Memoized welcome screen to prevent unnecessary re-renders
  const WelcomeScreen = React.memo(() => (
    <div className="welcome-screen" style={{
      textAlign: 'center',
      padding: '40px 20px',
      backgroundColor: 'white',
      borderRadius: '12px',
      boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
      margin: '20px 0'
    }}>
      <div style={{
        fontSize: '60px',
        marginBottom: '20px',
        color: '#4CAF50'
      }}>
        <svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" fill="currentColor" viewBox="0 0 16 16">
          <path d="M4 11H2v3h2v-3zm5-4H7v7h2V7zm5-5v12h-2V2h2zm-2-1a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1h2a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1h-2zM6 7a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v7a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V7zm-5 4a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1v-3z"/>
        </svg>
      </div>
      <h2 style={{
        fontSize: '24px',
        fontWeight: '600',
        color: '#333',
        marginBottom: '15px'
      }}>Selamat Datang di Stock Analyzer</h2>
      <p style={{
        fontSize: '16px',
        color: '#666',
        maxWidth: '600px',
        margin: '0 auto 20px',
        lineHeight: '1.6'
      }}>
        Pilih saham dari dropdown atau ketik kode saham di atas untuk melihat data historis dan grafik pergerakan harga.
        Contoh: <strong>BBCA.JK</strong> untuk Bank BCA, <strong>TLKM.JK</strong> untuk Telkom Indonesia, atau <strong>^JKSE</strong> untuk Indeks Harga Saham Gabungan.
      </p>
      <div style={{
        display: 'flex',
        flexWrap: 'wrap',
        justifyContent: 'center',
        gap: '10px',
        marginTop: '20px'
      }}>
        {['BBCA.JK', '^JKSE', 'ASII.JK', 'TLKM.JK'].map((sym, idx) => (
          <button
            key={sym}
            onClick={() => handleStockSelect(sym)}
            className="btn"
            style={{
              backgroundColor: ['#4CAF50', '#2196F3', '#9C27B0', '#FF5722'][idx],
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              padding: '8px 16px',
              cursor: 'pointer',
              fontSize: '14px'
            }}
          >
            {sym}
          </button>
        ))}
      </div>
    </div>
  ));

  // Render komponen berdasarkan currentPage
  const renderPage = () => {
    switch(currentPage) {
      case 'home':
        return <HomePage onNavigate={navigate} />; // Ganti handleNavigation dengan navigate
      case 'stocks':
        return <StockChart symbol={pageParams?.symbol || urlParams?.symbol} />;
      case 'news':
        return <NewsPage />;
      case 'about':
        return <AboutPage />;
    default:
      return <HomePage onNavigate={navigate} />; // Ganti handleNavigation dengan navigate
    }
  };

  // Render the appropriate page based on currentPage
  if (currentPage === 'home') {
  return (
    <DevNoticeProvider>
      <div className="app-container">
        <NavBar onNavigate={navigate} currentPage={currentPage} /> {/* Ganti handleNavigation dengan navigate */}
        <Suspense fallback={<div className="center-loader"><Loader /></div>}>
          <HomePage onNavigate={navigate} /> {/* Ganti handleNavigation dengan navigate */}
        </Suspense>
        <Footer />
      </div>
    </DevNoticeProvider>
  );
}

  if (currentPage === 'news') {
  return (
    <DevNoticeProvider>
      <div className="app-container">
        <NavBar onNavigate={navigate} currentPage={currentPage} /> {/* Ganti handleNavigation dengan navigate */}
        <Suspense fallback={<div className="center-loader"><Loader /></div>}>
          <HomePage onNavigate={navigate} /> {/* Ganti handleNavigation dengan navigate */}
        </Suspense>
        <Footer />
      </div>
    </DevNoticeProvider>
  );
}

  if (currentPage === 'about') {
  return (
    <DevNoticeProvider>
      <div className="app-container">
        <NavBar onNavigate={navigate} currentPage={currentPage} /> {/* Ganti handleNavigation dengan navigate */}
        <Suspense fallback={<div className="center-loader"><Loader /></div>}>
          <AboutPage />
        </Suspense>
        <Footer />
      </div>
    </DevNoticeProvider>
  );
}

  // MAIN RETURN STATEMENT - WRAP ALL WITH PROVIDER
  return (
    <DevNoticeProvider>
      <div className="App">
        <NavBar onNavigate={navigate} currentPage={currentPage} /> {/* Ganti handleNavigation dengan navigate */}
        
        <main id="main-content" className="content">
          <Suspense fallback={<div className="center-loader"><Loader /></div>}>
            {renderPage()}
          </Suspense>
        </main>
        
        <Footer />
        
        {/* DevNoticeModal di App.js untuk memastikan selalu muncul */}
        <DevNoticeModal />
      </div>
    </DevNoticeProvider>
  );
}

export default App;
